@startuml

class Home {}

class Department {}

class Room {}

class Bed {}

class Category {
  + price : float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + name : string
  + id : string
}

class Registration {
  + registrationDate : date
}

class Assessment {
  + resultStayType : StayType
}

class WaitingList {
  + position : int
}

class Stay {
  + status : string
  + startDate : date
  + endDate : date
}

class Invoice {
  + amount : float
  + outstandingAmount : float
  + status : string
}

class CreditNote {
  + amount : float
}

class PaymentEvent {
  + amount : float
  + date : date
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Category "1" -- "1" StayType

Inhabitant "1" -- "0..*" Stay
Stay "1" -- "1" StayType
Stay "1" -- "1" Bed

Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" WaitingList
WaitingList "1" -- "1" StayType

Stay "1" -- "1..*" Invoice
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

